const Interactive = () => {
  const [theme, setTheme] = useState<Theme>("auto");

  useEffect(() => {
    applyTheme(theme);
  }, [theme]);

  return (
    <div className="flex items-center gap-4">
      <ThemeToggle
        theme={theme}
        onToggle={() => setTheme(ThemeToggle.next(theme))}
      />
      <span className="text-sm text-on-surface-variant">
        Current: {theme}
      </span>
    </div>
  );
};

