const WelcomeBack = () => {
    const [selected, setSelected] = useState(
      args.selectedModelId ?? MODELS[0].id,
    );
    const [sent, setSent] = useState<string[]>([]);

    return (
        <div className="flex flex-col gap-8">
            <AgentGreeting
                greeting="Welcome Back, Nothing Chang"
                placeholder="plan something?"
                models={MODELS}
                selectedModelId={selected}
                onSelectModel={setSelected}
                onSend={(msg) => setSent((prev) => [...prev, msg])} />
            {sent.length > 0 && (
              <div className="mx-auto w-full max-w-2xl rounded-xl border border-outline-variant bg-surface-container-low p-3 text-sm">
                <div className="mb-1 font-medium text-on-surface">Sent</div>
                <ul className="flex flex-col gap-1 text-on-surface-variant">
                  {sent.map((m, i) => (
                    <li key={i}>· {m}</li>
                  ))}
                </ul>
              </div>
            )}
        </div>
    );
};

const FirstTime = () => <AgentGreeting
    greeting="Welcome to MirrorStack"
    subtitle="Tell the agent what you want to build."
    placeholder="what do you want to build?"
    models={MODELS}
    selectedModelId={SONNET} />;

const AppCreation = () => <AgentGreeting
    greeting="Let's create your app"
    subtitle="Describe the app — modules, data, surfaces — and the agent will scaffold it."
    placeholder="describe your app..."
    models={MODELS}
    selectedModelId={HAIKU} />;

const NoLogo = () => <AgentGreeting
    greeting="Welcome Back, Nothing Chang"
    placeholder="plan something?"
    models={MODELS}
    hideLogo />;

const User = () => (
  <AgentSidebarUserMessage content="Update my username to alice2 and turn on dark mode." />
);

const Agent = () => (
  <AgentSidebarAgentMessage content="Sure — I'll update your username and your appearance preference. Please confirm the changes below." />
);

