};

const History = () => {
  const [history, setHistory] = useState<AgentSidebarHistoryGroup[]>(mockAgentHistory);
  return (
    <div className="bg-surface-container">
      <AgentSidebarHeader
        sidebarWidth={420}
        onToggleCollapse={() => {}}
        onClose={() => {}}
        history={history}
        onSelectHistoryItem={(id) => console.log("open", id)}
        onRenameConversation={(id, title) => {
