/** Controlled tabs: titles from the consumer, history opens as a NEW tab,
 *  long titles ellipsize within the strip's allotment. */
export const ControlledTabs: StoryObj = {
  render: () => {
    const [tabs, setTabs] = useState<ChatTab[]>([
      { id: "conv-1", title: "New chat" },
      { id: "conv-2", title: "Update display name" },
    ]);
    const [activeTabId, setActiveTabId] = useState("conv-1");
    const nextIdRef = useRef(3);
    const openTab = (title: string) => {
      const tab = { id: `conv-${nextIdRef.current++}`, title };
      setTabs((prev) => [...prev, tab]);
      setActiveTabId(tab.id);
    };
    return (
      <div className="bg-surface-container">
        <AgentSidebarHeader
          sidebarWidth={420}
          onToggleCollapse={() => {}}
          onClose={() => {}}
          history={mockAgentHistory}
          onSelectHistoryItem={(id) => {
            const item = mockAgentHistory
              .flatMap((g) => g.items)
              .find((i) => i.id === id);
            openTab(item?.title ?? "New chat");
          }}
          tabs={tabs}
          activeTabId={activeTabId}
          onSelectTab={setActiveTabId}
          onCloseTab={(id) => {
            const next = tabs.filter((t) => t.id !== id);
            if (!next.length) return;
            setTabs(next);
            if (activeTabId === id) setActiveTabId(next[next.length - 1].id);
          }}
          onNewTab={() => openTab("New chat")}
        />
      </div>
    );
  },
};

/** Regression: ACTIVE tab is the LAST tab in the strip, right next to the
 *  header action icons. Tabs are flex-1, so the active tab's right edge sits
 *  flush at the strip's content edge and its notch overlay flares TAB_IR
 *  (12px) past it — the strip's pr-3 must absorb that curl so the dark
 *  on-background fill never paints under the + / collapse / close icons. */
export const ActiveLastTab: StoryObj = {
